class Solution {
public:
    vector<int> powerAfterInsertions(vector<int>& nums, int p, vector<vector<int>>& queries) {
        const long long MOD = 1000000007LL;
        vector<int> ans;
        for (auto& q : queries) {
            nums.push_back(q[0]);
            sort(nums.begin(), nums.end());
            long long x = nums[nums.size() - q[1]];
            long long base = p % MOD, res = 1;
            while (x) {
                if (x & 1) res = res * base % MOD;
                base = base * base % MOD;
                x >>= 1;
            }
            ans.push_back((int)res);
        }
        return ans;
    }
};

