class Solution {
    public int[] powerAfterInsertions(int[] nums, int p, int[][] queries) {
        final long MOD = 1000000007L;
        List<Integer> list = new ArrayList<>();
        for (int v : nums) list.add(v);
        int[] ans = new int[queries.length];
        for (int t = 0; t < queries.length; t++) {
            list.add(queries[t][0]);
            Collections.sort(list);
            long x = list.get(list.size() - queries[t][1]);
            long base = p % MOD, res = 1;
            while (x > 0) {
                if ((x & 1) == 1) res = res * base % MOD;
                base = base * base % MOD;
                x >>= 1;
            }
            ans[t] = (int) res;
        }
        return ans;
    }
}

