class Solution:
    def powerAfterInsertions(self, nums: List[int], p: int, queries: List[List[int]]) -> List[int]:
        MOD = 10**9 + 7
        vals = sorted(set(nums + [q[0] for q in queries]))
        m = len(vals)
        idx = {v: i + 1 for i, v in enumerate(vals)}
        bit = [0] * (m + 1)
        def upd(i):
            while i <= m:
                bit[i] += 1
                i += i & -i
        for v in nums:
            upd(idx[v])
        n, LOG = len(nums), m.bit_length()
        ans = []
        for val, k in queries:
            upd(idx[val])
            n += 1
            rem = n - k + 1
            i = 0
            for j in range(LOG, -1, -1):
                ni = i + (1 << j)
                if ni <= m and bit[ni] < rem:
                    i = ni
                    rem -= bit[i]
            ans.append(pow(p, vals[i], MOD))
        return ans

