class Solution {
public:
    vector<int> powerAfterInsertions(vector<int>& nums, int p, vector<vector<int>>& queries) {
        const long long MOD = 1000000007LL;
        vector<int> vals = nums;
        for (auto& q : queries) vals.push_back(q[0]);
        sort(vals.begin(), vals.end());
        vals.erase(unique(vals.begin(), vals.end()), vals.end());
        int m = vals.size(), n = nums.size();
        vector<int> bit(m + 1, 0);
        auto upd = [&](int i) { for (; i <= m; i += i & -i) bit[i]++; };
        for (int v : nums) upd(lower_bound(vals.begin(), vals.end(), v) - vals.begin() + 1);
        int LOG = 1;
        while ((1 << LOG) <= m) LOG++;
        vector<int> ans;
        for (auto& q : queries) {
            upd(lower_bound(vals.begin(), vals.end(), q[0]) - vals.begin() + 1);
            n++;
            long long rem = n - q[1] + 1;
            int i = 0;
            for (int j = LOG; j >= 0; j--) {
                int ni = i + (1 << j);
                if (ni <= m && bit[ni] < rem) { i = ni; rem -= bit[ni]; }
            }
            long long x = vals[i], base = p % MOD, res = 1;
            while (x) {
                if (x & 1) res = res * base % MOD;
                base = base * base % MOD;
                x >>= 1;
            }
            ans.push_back((int)res);
        }
        return ans;
    }
};

