class Solution {
    public int[] powerAfterInsertions(int[] nums, int p, int[][] queries) {
        final long MOD = 1000000007L;
        TreeSet<Integer> set = new TreeSet<>();
        for (int v : nums) set.add(v);
        for (int[] q : queries) set.add(q[0]);
        int[] vals = new int[set.size()];
        int t = 0;
        for (int v : set) vals[t++] = v;
        Map<Integer, Integer> idx = new HashMap<>();
        for (int i = 0; i < vals.length; i++) idx.put(vals[i], i + 1);
        int m = vals.length, n = nums.length;
        int[] bit = new int[m + 1];
        for (int v : nums) for (int i = idx.get(v); i <= m; i += i & -i) bit[i]++;
        int LOG = 1;
        while ((1 << LOG) <= m) LOG++;
        int[] ans = new int[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            for (int i = idx.get(queries[qi][0]); i <= m; i += i & -i) bit[i]++;
            n++;
