            int i = 0;
            for (int j = LOG; j >= 0; j--) {
                int ni = i + (1 << j);
                if (ni <= m && bit[ni] < rem) { i = ni; rem -= bit[ni]; }
            }
            long x = vals[i], base = p % MOD, res = 1;
